interface.signature:
POST /api/auth/register
Request Body: {
  email: string (RFC 5322 validated),
  password: string (min 8 chars, 1 uppercase, 1 number, 1 special),
  name: string
}
Response: {
  success: boolean,
  user?: User,
  error?: string
}

POST /api/auth/verify-email
Request Body: {
  token: string (32+ characters, URL-safe)
}
Response: {
  success: boolean,
  message?: string,
  error?: string
}

async register(userData: RegisterData): Promise<AuthResponse>
RegisterData: {
  email: string,
  password: string,
  name: string
}

SignupForm({ onSuccess?: () => void, className?: string })
Props: {
  onSuccess?: callback function,
  className?: string for styling
}

PasswordStrengthMeter({ password: string })
Props: {
  password: string to analyze
}
Returns: Visual strength indicators (weak/medium/strong)
